mapper.select:
select s.cn_share_id, s.cn_share_title, s.cn_share_body, s.cn_note_id, s.cn_share_status, u.cn_user_nick as cn_share_author from cn_share s left join cn_note n on n.cn_note_id = s.cn_note_id left join cn_user u on u.cn_user_id = n.cn_user_id
s.cn_share_title like #{keyword}
order by s.cn_share_id limit #{pageSize} offset #{begin}
